mapper.select:
select snapshot_id, source_url, final_url, source_kind, http_status, content_type, content_hash, content, content_size, title,
       first_seen_time, last_seen_time, seen_count, fetched_by, remark
from abr_source_snapshot where snapshot_id = #{snapshotId}

mapper.delete:
delete from abr_source_snapshot s
where s.last_seen_time < #{cutoff}
  and not exists (select 1 from abr_field_source f where f.snapshot_id = s.snapshot_id)
